type LucaLogoProps = {
  variant?: "full" | "wordmark" | "mark";
  className?: string;
  /** Texto accesible. Pasa "" si el logo es decorativo junto a texto visible. */
  title?: string;
};

export const VIEWBOX = {
  full: "280 405 1150 1550",
  wordmark: "280 1505 1150 450",
  mark: "430 405 760 1060",
} as const;

export function LucaLogo({
  variant = "full",
  className,
  title = "LUCA Pizza Napoletana",
}: LucaLogoProps) {
  const showMark = variant !== "wordmark";
  const showWordmark = variant !== "mark";
  const decorative = title === "";

  return (
    <svg
      viewBox={VIEWBOX[variant]}
      fill="currentColor"
      className={cn("h-auto w-full", className)}
      role={decorative ? undefined : "img"}
      aria-hidden={decorative ? true : undefined}
      aria-label={decorative ? undefined : title}
      focusable="false"
    >
      {showMark && (
        <g>
          {/* Trazo vertical del gesto */}
          <path d={LOGO_PATHS.stroke} />
          {/* Mano */}
          <path d={LOGO_PATHS.hand} />
        </g>
      )}
      {showWordmark && (
        <g>
          {/* L */}
          <path d={LOGO_PATHS.L} />
          {/* U */}
          <path d={LOGO_PATHS.U} />
          {/* C */}
          <path d={LOGO_PATHS.C} />
          {/* A */}
          <path fillRule="evenodd" d={LOGO_PATHS.A} />
        </g>
      )}
    </svg>
  );
}
